def solution(index):
    if index < 2:
        return index
    previous = 0
    current = 1
    for _ in range(2, index + 1):
        previous, current = current, previous + current
    return current

def solution(sequence):
    seen = set()
    result = []
    for element in sequence:
        if element not in seen:
            seen.add(element)
            result.append(element)
    return result

def solution(entries):
