    for entry in entries:
        if entry % 2 == 0:
            counter += 1
    return counter

def solution(text):
    cleaned = text.lower()
    start = 0
    end = len(cleaned) - 1
    while start < end:
        if cleaned[start] != cleaned[end]:
            return False
        start += 1
        end -= 1
    return True

def solution(matrix):
    rows = len(matrix)
    columns = len(matrix[0]) if rows else 0
    transposed = []
    for col in range(columns):
        new_row = []
        for row in range(rows):
            new_row.append(matrix[row][col])
        transposed.append(new_row)
    return transposed

def solution(sentence):
    counts = {}
    for word in sentence.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def solution(base, exponent):
    if exponent == 0:
        return 1
    half = solution(base, exponent // 2)
    if exponent % 2 == 0:
        return half * half
    return base * half * half
